import pty, os, subprocess, time, select, struct, fcntl, termios

def run_pty(args, cols=80, rows=24, timeout=1.5):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))
    p = subprocess.Popen(['./executable']+args, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    os.set_blocking(master, False)
    output = b""
    start = time.time()
    while time.time() - start < timeout:
        r,_,_ = select.select([master], [], [], 0.2)
        if r:
            try:
                data = os.read(master, 8192)
                if data:
                    output += data
                else:
                    break
            except OSError:
                break
        if p.poll() is not None:
            try:
                while True:
                    data = os.read(master, 8192)
                    if not data: break
                    output += data
            except: pass
            break
    try:
        p.terminate()
        time.sleep(0.2)
        if p.poll() is None:
            p.kill()
    except: pass
    try: os.close(master)
    except: pass
    return p.returncode, output

