import subprocess, tempfile, os
def render(obj_content, w='40', h='20'):
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        p=os.path.join(td,"m.obj")
        with open(p,'w') as f:
            f.write(obj_content)
        r=subprocess.run(['./executable','-b',p,'image','-w',w,'-h',h], capture_output=True, timeout=10)
        txt=r.stdout.decode() if r.returncode==0 else ""
        lines=txt.split("\n")
        if lines and lines[-1]=="":
            lines=lines[:-1]
        return txt, lines

def bbox(lines):
    min_x,max_x,min_y,max_y=None,None,None,None
    for y,line in enumerate(lines):
        for x,ch in enumerate(line):
            if ch!=' ':
                if min_x is None or x<min_x: min_x=x
                if max_x is None or x>max_x: max_x=x
                if min_y is None or y<min_y: min_y=y
                if max_y is None or y>max_y: max_y=y
    return (min_x,max_x,min_y,max_y)

for dy in [0, 0.5, 1, -1, -0.5]:
    obj=f"v 0 {dy} 0\nv 1 {dy} 0\nv 0 {dy+1} 0\nf 1 2 3\n"
    txt,lines=render(obj)
    print(f"dy={dy} bbox={bbox(lines)} nlines={len(lines)}")
    for l in lines:
        print(f"  {repr(l[:50])} len={len(l)}")
    print()
PY
"}

