import subprocess, os, time, select, struct, fcntl, termios, pty

def test_key(key, name):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 20, 40, 0, 0))
    proc = subprocess.Popen(['./executable','assets/test_model.obj'], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    os.set_blocking(master, False)
    output=b""
    start=time.time()
    sent=False
    exit_time=None
    while time.time()-start<2.0:
        r,_,_=select.select([master],[],[],0.1)
        if r:
            try:
                data=os.read(master,16384)
                if data: output+=data
            except: break
        if not sent and time.time()-start>0.5:
            try:
                os.write(master, key)
                print(f"[{name}] sent {repr(key)} at {time.time()-start:.2f}s")
            except Exception as e:
                print(f"send failed: {e}")
            sent=True
        if proc.poll() is not None and exit_time is None:
            exit_time=time.time()-start
            print(f"[{name}] proc exited with {proc.returncode} at {exit_time:.2f}s")
            # Drain remaining output after exit?
            time.sleep(0.2)
            try:
                while True:
                    r2,_,_=select.select([master],[],[],0.1)
                    if not r2: break
                    data=os.read(master,16384)
                    if not data: break
                    output+=data
            except: pass
            break
    if proc.poll() is None:
        print(f"[{name}] still running after 2s, killing")
        try:
            proc.terminate()
            time.sleep(0.2)
            if proc.poll() is None: proc.kill()
        except: pass
    else:
        print(f"[{name}] output len={len(output)}, last 500={repr(output[-500:])}")
    try: os.close(master)
    except: pass
    print()

for key,name in [(b'q','q'),(b'Q','Q'),(b'\x03','Ctrl-C'),(b'\x04','Ctrl-D'),(b'\n','Enter'),(b'qq','qq'),(b'x','x')]:
