}

fn help_help(bin: &str) -> String {
    format!("{}-help \nPrints this message or the help of the given subcommand(s)\n\nUSAGE:\n    {} help [subcommand]...\n\nARGS:\n    <subcommand>...    The subcommand whose help message to display\n", bin, bin)
