fn load_single(filename: &str) -> Result<Model, String> {
    let p = Path::new(filename);
    let ext_opt = p.extension().and_then(|s| s.to_str());
    let ext_lower = ext_opt.map(|s| s.to_lowercase());
    match ext_lower.as_deref() {
        None => {
            return Err(format!("filename: [{}] couldn't load, couldn't determine filename extension. ", filename));
        },
        Some("obj") => {
            return load_obj(filename);
        },
        Some("stl") => {
            return load_stl(filename);
        },
        Some(_) => {
            return Err(format!("filename: [{}] couldn't load, unknown filename extension. ", filename));
        }
    }
}

fn load_obj(filename: &str) -> Result<Model, String> {
    use std::fs::File;
    use std::io::{BufRead, BufReader};
    let file = match File::open(filename) {
        Ok(f) => f,
        Err(_) => {
            return Err(format!("filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed", filename));
        }
    };
    let reader = BufReader::new(file);
    let mut vertices: Vec<[f32;3]> = Vec::new();
    let mut faces: Vec<Vec<usize>> = Vec::new();
    let mut face_mat_names: Vec<Option<String>> = Vec::new();
    let mut current_mat: Option<String> = None;
    let mut mtllib: Option<String> = None;
    for line_res in reader.lines() {
        let line = match line_res {
            Ok(l) => l,
            Err(_) => {
                return Err(format!("filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed", filename));
            }
        };
        let t = line.trim();
        if t.is_empty() || t.starts_with('#') { continue; }
        if t.starts_with("mtllib ") {
            let rest = t["mtllib ".len()..].trim();
            let first = rest.split_whitespace().next().unwrap_or("").to_string();
            if !first.is_empty() {
                mtllib = Some(first);
            }
            continue;
        } else if t.starts_with("usemtl ") {
            let rest = t["usemtl ".len()..].trim().to_string();
            if rest.is_empty() {
                current_mat = None;
            } else {
                current_mat = Some(rest);
            }
            continue;
        } else if t.starts_with("v ") {
            let parts: Vec<&str> = t[2..].split_whitespace().collect();
            if parts.len() < 3 { continue; }
            let x: f32 = parts[0].parse().unwrap_or(0.0);
            let y: f32 = parts[1].parse().unwrap_or(0.0);
            let z: f32 = parts[2].parse().unwrap_or(0.0);
            vertices.push([x,y,z]);
            continue;
        } else if t.starts_with("f ") {
            let rest = t[2..].trim();
            if rest.is_empty() { continue; }
            let tokens: Vec<&str> = rest.split_whitespace().collect();
            let mut idxs: Vec<usize> = Vec::new();
            for tok in tokens {
                let v_part = tok.split('/').next().unwrap_or("");
                if v_part.is_empty() { continue; }
                let vi: i32 = match v_part.parse() {
                    Ok(n) => n,
                    Err(_) => continue,
                };
                let idx0 = if vi > 0 {
                    (vi as usize) - 1
                } else if vi < 0 {
                    if vertices.is_empty() { continue; }
                    let rel = vertices.len() as i32 + vi;
                    if rel < 0 { continue; }
                    rel as usize
                } else {
                    continue;
                };
                idxs.push(idx0);
            }
            if idxs.len() < 3 { continue; }
            for k in 1..idxs.len()-1 {
                let tri = vec![idxs[0], idxs[k], idxs[k+1]];
                faces.push(tri);
                face_mat_names.push(current_mat.clone());
            }
            continue;
        } else {
            continue;
        }
    }
    let mut materials: Vec<Material> = Vec::new();
    use std::collections::HashMap;
    let mut name_to_idx: HashMap<String, usize> = HashMap::new();
    if let Some(mtl_file) = mtllib {
        let obj_path = Path::new(filename);
        let mtl_path = if let Some(parent) = obj_path.parent() {
            if parent.as_os_str().is_empty() {
                Path::new(&mtl_file).to_path_buf()
            } else {
                parent.join(&mtl_file)
            }
        } else {
            Path::new(&mtl_file).to_path_buf()
        };
        let mtl_content = load_mtl(&mtl_path);
        let mut cur_name: Option<String> = None;
        let mut cur_kd: [f32;3] = [0.0,0.0,0.0];
        let mut has_cur = false;
        for line in mtl_content.lines() {
            let t = line.trim();
            if t.is_empty() || t.starts_with('#') { continue; }
            if t.starts_with("newmtl ") {
                if has_cur {
                    if let Some(nm) = cur_name.take() {
                        let idxm = materials.len();
                        name_to_idx.insert(nm.clone(), idxm);
                        materials.push(Material{name: nm, diffuse: cur_kd});
                    }
                }
                let rest = t["newmtl ".len()..].trim().to_string();
                cur_name = Some(rest);
                cur_kd = [0.0,0.0,0.0];
                has_cur = true;
                continue;
            } else if t.starts_with("Kd") && (t.len()==2 || t[2..].starts_with(char::is_whitespace)) {
                let rest = if t.len()>2 { t[2..].trim() } else { "" };
                if rest.is_empty() {
                    continue;
                }
                let parts: Vec<&str> = rest.split_whitespace().collect();
                let mut vals = [0.0f32;3];
                for (ii,pp) in parts.iter().take(3).enumerate() {
                    vals[ii] = pp.parse().unwrap_or(0.0);
                }
                cur_kd = vals;
                continue;
            } else {
                continue;
            }
        }
        if has_cur {
            if let Some(nm) = cur_name.take() {
                let idxm = materials.len();
                name_to_idx.insert(nm.clone(), idxm);
                materials.push(Material{name: nm, diffuse: cur_kd});
            }
        }
    }
    let mut indices: Vec<usize> = Vec::new();
    let mut mat_ids: Vec<Option<usize>> = Vec::new();
    for (fi, tri) in faces.iter().enumerate() {
        for &vi in tri {
            indices.push(vi);
        }
        let mat_name_opt = &face_mat_names[fi];
        let mid = if let Some(nm) = mat_name_opt {
            name_to_idx.get(nm).cloned()
        } else {
            None
        };
        mat_ids.push(mid);
    }
    Ok(Model{vertices, indices, material_ids: mat_ids, materials, is_stl:false})
}

fn load_stl(filename: &str) -> Result<Model, String> {
    use std::fs::File;
    use std::io::Read;
    let mut file = match File::open(filename) {
        Ok(f)=>f,
        Err(e)=>{
            return Err(format!("filename: [{}] couldn't load, STL load failed. {}", filename, e));
        }
    };
    let mut buf = Vec::new();
    match file.read_to_end(&mut buf) {
        Ok(_)=>{},
        Err(e)=>{
            return Err(format!("filename: [{}] couldn't load, stl_io couldnt parse STL. {}", filename, e));
        }
    }
    if buf.len() < 84 {
        return Err(format!("filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer", filename));
    }
    let count_bytes = &buf[80..84];
    let facet_count = u32::from_le_bytes([count_bytes[0],count_bytes[1],count_bytes[2],count_bytes[3]]) as usize;
    let expected_binary_len = 84 + facet_count.checked_mul(50).unwrap_or(usize::MAX);
    let is_binary = expected_binary_len == buf.len();
    let starts_with_solid = buf.len()>=5 && &buf[0..5]==b"solid";
    let use_binary = if !starts_with_solid { true } else { is_binary };
    if use_binary {
        if buf.len() < 84+facet_count*50 {
            return Err(format!("filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer", filename));
        }
        let mut vertices: Vec<[f32;3]> = Vec::new();
        let mut indices: Vec<usize> = Vec::new();
        let mut offset = 84usize;
        for _ in 0..facet_count {
            offset += 12;
            let mut tri_idx: Vec<usize> = Vec::new();
            for _ in 0..3 {
                if offset+12 > buf.len() {
                    return Err(format!("filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer", filename));
                }
                let x = f32::from_le_bytes([buf[offset],buf[offset+1],buf[offset+2],buf[offset+3]]);
                let y = f32::from_le_bytes([buf[offset+4],buf[offset+5],buf[offset+6],buf[offset+7]]);
                let z = f32::from_le_bytes([buf[offset+8],buf[offset+9],buf[offset+10],buf[offset+11]]);
                offset+=12;
                let vi = vertices.len();
                vertices.push([x,y,z]);
                tri_idx.push(vi);
            }
            offset+=2;
            for &vi in &tri_idx { indices.push(vi); }
        }
        let materials = vec![Material{name:"stl_default".to_string(), diffuse:[1.0,1.0,0.0]}];
        let mat_ids = vec![Some(0usize); facet_count];
        Ok(Model{vertices, indices, material_ids: mat_ids, materials, is_stl:true})
    } else {
        let text = match String::from_utf8(buf) {
            Ok(s)=>s,
            Err(_)=>{
                return Err(format!("filename: [{}] couldn't load, stl_io couldnt parse STL. failed to fill whole buffer", filename));
            }
        };
        let mut vertices: Vec<[f32;3]> = Vec::new();
        let mut indices: Vec<usize> = Vec::new();
        for line in text.lines() {
            let t = line.trim();
            if t.starts_with("vertex ") || t.starts_with("vertex\t") {
                let rest = t["vertex".len()..].trim();
                let parts: Vec<&str> = rest.split_whitespace().collect();
                if parts.len()<3 { continue; }
                let x: f32 = parts[0].parse().unwrap_or(0.0);
                let y: f32 = parts[1].parse().unwrap_or(0.0);
                let z: f32 = parts[2].parse().unwrap_or(0.0);
                let vi = vertices.len();
                vertices.push([x,y,z]);
                indices.push(vi);
            }
        }
        let facet_count = indices.len()/3;
        let valid_len = facet_count*3;
        vertices.truncate(valid_len);
        indices.truncate(valid_len);
        let materials = vec![Material{name:"stl_default".to_string(), diffuse:[1.0,1.0,0.0]}];
        let mat_ids = vec![Some(0usize); facet_count];
        Ok(Model{vertices, indices, material_ids: mat_ids, materials, is_stl:true})
    }
}
